<?php defined('ABSPATH') || exit;$base=home_url('/companion/');$root='dungeon-master/campaigns/'.$campaign->id().'/personae'; ?>
<section class="gmrc-personae"><header class="gmrc-personae__hero"><div><p class="gmrc-dm-desk__eyebrow"><?php echo esc_html($persona->kindLabel()); ?> · <?php echo $persona->isKeeperOnly()?'Keeper only':'Player-visible'; ?><?php echo $persona->isArchived()?' · Archived':''; ?></p><h1><?php echo esc_html($persona->name()); ?></h1><?php if($persona->role()!==''): ?><p><?php echo esc_html($persona->role()); ?></p><?php endif; ?></div><?php if(!$campaign->isArchived()&&!$persona->isArchived()): ?><a class="gmrc-personae-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$persona->id().'/edit',$base)); ?>">Edit Record</a><?php endif; ?></header>
<article class="gmrc-personae-page"><section><h2>At a glance</h2><p><?php echo $persona->summary()!==''?esc_html($persona->summary()):'No summary has been written yet.'; ?></p></section><?php if($faction): ?><section><h2>Faction / allegiance</h2><p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$faction->id(),$base)); ?>"><?php echo esc_html($faction->name()); ?></a></p></section><?php endif; ?><section><h2>Keeper’s notes</h2><div><?php echo $persona->notes()!==''?wpautop(esc_html($persona->notes())):'<p>No private notes have been written yet.</p>'; ?></div></section><section class="gmrc-personae-page__board"><h2>Conspiracy Board</h2><p>This stable identity is ready to become a future board pin without duplicating its campaign record.</p></section></article>
<?php if($persona->isFaction()&&$members!==[]): ?><section class="gmrc-personae-members"><h2>People aligned with <?php echo esc_html($persona->name()); ?></h2><div class="gmrc-personae-grid"><?php foreach($members as $member): ?><article class="gmrc-personae-card"><h3><?php echo esc_html($member->name()); ?></h3><?php if($member->role()!==''): ?><p><?php echo esc_html($member->role()); ?></p><?php endif; ?><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$member->id(),$base)); ?>">Open person →</a></article><?php endforeach; ?></div></section><?php endif; ?>
<?php if(!$campaign->isArchived()&&!$persona->isArchived()): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="gmrc-personae-archive-form" onsubmit="return confirm('Archive this Dramatis Personae record?');"><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="gmrc_route" value="<?php echo esc_attr($root.'/'.$persona->id().'/archive'); ?>"><input type="hidden" name="_method" value="POST"><input type="hidden" name="gmrc_nonce" value="<?php echo esc_attr(wp_create_nonce('gmrc_dm_personae_'.$campaign->id())); ?>"><button type="submit">Archive record</button></form><?php endif; ?><p class="gmrc-personae-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root,$base)); ?>">← Back to Dramatis Personae</a></p></section>
